"""Read the fixed-width binary dataset generated by AiLipSyncTrainingDataRecorder."""

import json
from pathlib import Path

import numpy as np
import torch
from torch.utils.data import Dataset


class LipSyncDataset(Dataset):
    """Inputs are PCM float32 rows; targets are normalized viseme probability rows."""

    def __init__(self, dataset_dir: str | Path):
        dataset_dir = Path(dataset_dir)
        metadata_path = dataset_dir / "metadata.json"
        with metadata_path.open("r", encoding="utf-8") as metadata_file:
            self.metadata = json.load(metadata_file)

        self.input_size = int(self.metadata["inputShape"][0])
        self.output_size = int(self.metadata["outputShape"][0])
        self.labels = self.metadata["outputLabels"]
        expected_count = int(self.metadata["recordCount"])

        inputs = np.fromfile(dataset_dir / self.metadata["inputFile"], dtype="<f4")
        targets = np.fromfile(dataset_dir / self.metadata["outputFile"], dtype="<f4")
        if inputs.size % self.input_size != 0 or targets.size % self.output_size != 0:
            raise ValueError("Binary file size does not match metadata tensor shapes.")

        self.inputs = inputs.reshape(-1, self.input_size)
        self.targets = targets.reshape(-1, self.output_size)
        if len(self.inputs) != len(self.targets) or len(self.inputs) != expected_count:
            raise ValueError("metadata.json, inputs.f32, and labels.f32 have inconsistent row counts.")

        valid_rows = self.targets.sum(axis=1) > 0
        self.inputs = self.inputs[valid_rows]
        self.targets = self.targets[valid_rows]

    def __len__(self) -> int:
        return len(self.inputs)

    def __getitem__(self, index: int):
        return torch.from_numpy(self.inputs[index]), torch.from_numpy(self.targets[index])
